<?php use App\Core\CSRF; ?>
<section class="container py-5" style="max-width:760px"><div class="card"><div class="card-body p-4"><h1 class="h3">Remarcar reserva</h1><form method="get" class="row g-2 mb-4"><div class="col"><input type="date" name="date" value="<?=htmlspecialchars($date)?>" min="<?=date('Y-m-d')?>" class="form-control"></div><div class="col-auto"><button class="btn btn-outline-primary">Ver horários</button></div></form><form method="post" action="/auto/booking/<?=htmlspecialchars($token)?>/reschedule"><?=CSRF::field()?><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach($slots as $s):?><label class="btn btn-outline-primary"><input type="radio" class="d-none" name="slot" onclick="document.getElementById('rs-bay').value='<?=$s['bay_id']?>';document.getElementById('rs-start').value='<?=htmlspecialchars($s['starts_at'])?>'"> <?=htmlspecialchars($s['time'].' · '.$s['bay_name'])?></label><?php endforeach;?><?php if(!$slots):?><div class="alert alert-warning w-100">Sem disponibilidade nessa data.</div><?php endif;?></div><input type="hidden" name="bay_id" id="rs-bay"><input type="hidden" name="starts_at" id="rs-start"><button class="btn btn-primary">Salvar nova data</button></form></div></div></section>
